CREATE DATABASE IF NOT EXISTS assetvault CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE assetvault;
CREATE TABLE IF NOT EXISTS roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(32) NOT NULL UNIQUE);
INSERT IGNORE INTO roles(name) VALUES ('Administrator'),('Editor'),('Viewer');
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id TINYINT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_users_role FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(150) NOT NULL, file_size BIGINT UNSIGNED NOT NULL, category VARCHAR(32) NOT NULL, sensitivity ENUM('Public','Internal','Confidential') NOT NULL DEFAULT 'Internal', tags VARCHAR(500) NOT NULL DEFAULT '', uploaded_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL DEFAULT NULL, INDEX idx_assets_created(created_at), INDEX idx_assets_category(category), CONSTRAINT fk_assets_user FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS asset_access_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT UNSIGNED NOT NULL, requester_id BIGINT UNSIGNED NOT NULL, owner_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','approved','denied') NOT NULL DEFAULT 'pending', message VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_asset_requester(asset_id,requester_id), INDEX idx_access_owner(owner_id,status), CONSTRAINT fk_access_asset FOREIGN KEY(asset_id) REFERENCES assets(id), CONSTRAINT fk_access_requester FOREIGN KEY(requester_id) REFERENCES users(id), CONSTRAINT fk_access_owner FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(32) NOT NULL, asset_id BIGINT UNSIGNED NULL, details VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_created(created_at), CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id));
